function setupCustomPlayer(video) {
  let isDragging = false, startX = 0, startTime = 0, longPressTimer = null;
  const LONG_PRESS_DELAY = 300, NORMAL_SPEED = 1.25, FAST_SPEED = 3;
  let wasPaused = false;
  function handleTouchStart(e) { startX = e.touches[0].clientX; startTime = video.currentTime; wasPaused = video.paused; longPressTimer = setTimeout(() => { video.playbackRate = FAST_SPEED; if (wasPaused) video.play(); }, LONG_PRESS_DELAY); }
  function handleTouchMove(e) { if (longPressTimer) { clearTimeout(longPressTimer); longPressTimer = null; } const dx = e.touches[0].clientX - startX; if (Math.abs(dx) > 10) { if (!isDragging) { video.pause(); isDragging = true; } const change = (dx / video.clientWidth) * video.duration; video.currentTime = Math.max(0, Math.min(startTime + change, video.duration)); } }
  function handleTouchEnd() { if (longPressTimer) { clearTimeout(longPressTimer); longPressTimer = null; } if (isDragging) { video.playbackRate = NORMAL_SPEED; video.play(); isDragging = false; } else if (video.playbackRate === FAST_SPEED) { video.playbackRate = NORMAL_SPEED; if (wasPaused) video.pause(); } }
  video.addEventListener('touchstart', handleTouchStart);
  video.addEventListener('touchmove', handleTouchMove);
  video.addEventListener('touchend', handleTouchEnd);
  video.playbackRate = NORMAL_SPEED;
}
setTimeout(function(){ var v=document.querySelector('#stack video'); if(v) setupCustomPlayer(v); }, 1500);

